package com.metaplatform.agent.evidence;
import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="claim_records") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class ClaimEntity { @Id @Column(name="claim_id",length=64) private String claimId; @Column(name="run_id",nullable=false,length=64) private String runId; @Column(name="task_id",length=64) private String taskId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=32) private ClaimType type; @Column(nullable=false,columnDefinition="TEXT") private String content; @Column(nullable=false,precision=4,scale=3) private BigDecimal confidence; @Lob @JdbcTypeCode(SqlTypes.JSON) @Column(name="evidence_refs",nullable=false,columnDefinition="jsonb") private String evidenceRefs; @Column(name="generated_by_agent_id",nullable=false,length=128) private String generatedByAgentId; @Column(name="generated_by_model",nullable=false,length=128) private String generatedByModel; @Lob @JdbcTypeCode(SqlTypes.JSON) @Column(name="tool_call_ids",columnDefinition="jsonb") private String toolCallIds; @Column(name="prompt_snapshot_id",length=64) private String promptSnapshotId; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; }
